local COURSE = HttpService:JSONDecode(COURSE_JSON)
local NODES = {}
for _, n in ipairs(COURSE.nodes) do NODES[n.id] = n end
local MODELS = {}
for _, m in ipairs(COURSE.bot_models) do MODELS[m.id] = m end
local W = COURSE.world

local GROUND_HEIGHT = 10
local GROUND_Y = -(GROUND_HEIGHT * 0.5)
local OCEAN_TOP_Y = -0.5
local PEN = NODES.N0.zone.c
local SPAWN = Vector3.new(PEN[1], 3, PEN[2])
local HOP_COST_J = 2.61      -- measured mean energy per hop (island_runway_fly)
local HOP_AIR_S = 2.22       -- measured mean airborne time per hop
local HOP_RULE = 1.15        -- hop only if reserve >= 1.15 x cost
local DEFAULT_RESERVE_J = 13 -- assumption: mid-point of the U(10, 16) J reserve in island_drone_course
local SWIM_SPEED = 0.75      -- triathlon base swim speed (sim parameter)
local REEF_HOLD_S = 10

local terrainPhysics = PhysicalProperties.new(2.0, 1.4, 0.0, 1.0, 1.0)

local function part(name, size, pos, color, opts)
    opts = opts or {}
    local p = Instance.new("Part")
    p.Name = name
    p.Size = size
    if opts.yaw then
        p.CFrame = CFrame.new(pos) * CFrame.Angles(0, math.rad(opts.yaw), 0)
    else
        p.Position = pos
    end
    p.Anchored = true
    p.CanCollide = opts.collide ~= false
    p.Color = color
    p.Material = opts.material or Enum.Material.SmoothPlastic
    if opts.transparency then p.Transparency = opts.transparency end
    if opts.role then p:SetAttribute("RenderRole", opts.role) end
    if opts.terrain then p.CustomPhysicalProperties = terrainPhysics end
    p:SetAttribute("CourseTag", opts.tag or "course")
    p.Parent = Workspace
    return p
end

--------------------------------------------------------------------------------
-- ISLAND (ocean + ground; centre box split to open the bay)
--------------------------------------------------------------------------------
part("Ocean", Vector3.new(600, 0.45, 600), Vector3.new(0, OCEAN_TOP_Y - 0.225, 0), Color3.fromRGB(52, 128, 168),
    { collide = false, material = Enum.Material.Glass, transparency = 0.18, role = "Ocean", tag = "ocean" })

local bay = W.bay
local function box(name, x0, x1, z0, z1)
    part(name, Vector3.new(x1 - x0, GROUND_HEIGHT, z1 - z0), Vector3.new((x0 + x1) / 2, GROUND_Y, (z0 + z1) / 2),
        Color3.fromRGB(85, 239, 196), { role = "Ground", terrain = true, tag = "ground" })
end
-- GroundCenter was {96 x 100} at (-2, 0): x -50..46, z -50..50
box("GroundCenterNorth", -50, 46, bay.max[2], 50)
box("GroundCenterSW", -50, bay.min[1], -50, bay.max[2])
box("GroundCenterSE", bay.max[1], 46, -50, bay.max[2])
box("GroundN", -11, 31, 49, 63)
box("GroundS", -30, 6, -62, -48)
box("GroundW", -63, -49, -23, 17)
box("GroundE", 43, 53, -24, 34)
-- swim floor: invisible, lets humanoids wade the bay (Clawblox has no swimming physics)
part("SwimFloor", Vector3.new(bay.max[1] - bay.min[1], 0.4, bay.max[2] - bay.min[2]),
    Vector3.new((bay.min[1] + bay.max[1]) / 2, bay.swim_floor_y - 0.2, (bay.min[2] + bay.max[2]) / 2),
    Color3.fromRGB(40, 90, 120), { transparency = 1, tag = "swimfloor" })
-- reef strip across the bay mouth
local reef = W.reef
part("Reef", Vector3.new(reef.max[1] - reef.min[1], 1, reef.max[2] - reef.min[2]),
    Vector3.new((reef.min[1] + reef.max[1]) / 2, reef.top_y - 0.5, (reef.min[2] + reef.max[2]) / 2),
    Color3.fromRGB(150, 120, 96), { role = "Rock", tag = "reef" })
local tip = NODES.N1b.zone.c
part("ReefBeacon", Vector3.new(0.6, 3, 0.6), Vector3.new(tip[1], 1.5, tip[2]), Color3.fromRGB(255, 220, 80), { collide = false, tag = "beacon" })
local buoy = NODES.N1.waypoints.buoy
part("Buoy", Vector3.new(1, 1.5, 1), Vector3.new(buoy[1], -0.3, buoy[2]), Color3.fromRGB(255, 120, 40), { collide = false, tag = "buoy" })

-- boundaries (invisible walls at +-80, as in mesa-island)
for _, b in ipairs({ { 0, 83, 172, 6 }, { 0, -83, 172, 6 }, { 83, 0, 6, 172 }, { -83, 0, 6, 172 } }) do
    part("Boundary", Vector3.new(b[3], 80, b[4]), Vector3.new(b[1], 40, b[2]), Color3.fromRGB(255, 255, 255), { transparency = 1, tag = "boundary" })
end

--------------------------------------------------------------------------------
-- COURSE PARTS
--------------------------------------------------------------------------------
local function pad(name, c, r, color)
    return part(name, Vector3.new(r * 2, 0.1, r * 2), Vector3.new(c[1], 0.05, c[2]), color, { collide = false, tag = "pad" })
end
pad("Pad_N0_StartPen", PEN, NODES.N0.zone.r, Color3.fromRGB(255, 255, 255))
local rw = W.runway
part("Runway", Vector3.new(rw.width, 0.06, rw.z[2] - rw.z[1]), Vector3.new(rw.x, 0.03, (rw.z[1] + rw.z[2]) / 2), Color3.fromRGB(70, 70, 76), { collide = false, tag = "runway" })
part("RunwayStartLine", Vector3.new(rw.width, 0.08, 0.5), Vector3.new(rw.x, 0.04, NODES.N2.zone.min[2]), Color3.fromRGB(255, 255, 255), { collide = false, tag = "line" })
part("RunwayGoalLine", Vector3.new(rw.width, 0.08, 0.5), Vector3.new(rw.x, 0.04, NODES.N3.zone.max[2]), Color3.fromRGB(255, 255, 255), { collide = false, tag = "line" })
for i, o in ipairs(W.runway_obstacles) do
    local s = o.size
    part("Runway_" .. o.kind .. "_" .. i, Vector3.new(s[1], s[2], s[3]), Vector3.new(o.c[1], s[2] / 2, o.c[2]),
        o.kind == "pallet" and Color3.fromRGB(181, 140, 90) or Color3.fromRGB(200, 205, 215), { yaw = o.yaw, tag = "obstacle" })
end
-- drone gates: square frame (4 bars) on a post, plus take-off, landing and on-foot check-in pads
local OPEN = NODES.N4.gate_opening
-- on-foot check-in pad: 1.5 studs from the post on the take-off side, so walkers reach it without crossing the post
local function checkinPos(g)
    local dx, dz = g.takeoff[1] - g.c[1], g.takeoff[2] - g.c[2]
    local d = math.max(1e-6, math.sqrt(dx * dx + dz * dz))
    return { g.c[1] + 1.5 * dx / d, g.c[2] + 1.5 * dz / d }
end
for _, g in ipairs(NODES.N4.gates) do
    local cx, cz, h = g.c[1], g.c[2], g.h
    local dx, dz = g.landing[1] - g.takeoff[1], g.landing[2] - g.takeoff[2]
    local yaw = math.deg(math.atan2(dx, dz))  -- frame faces the flight line
    local cf = CFrame.new(cx, h, cz) * CFrame.Angles(0, math.rad(yaw), 0)
    local col = Color3.fromRGB(255, 176, 32)
    for _, bar in ipairs({ { 0, OPEN / 2 + 0.3, OPEN + 1.2, 0.6 }, { 0, -OPEN / 2 - 0.3, OPEN + 1.2, 0.6 },
                           { OPEN / 2 + 0.3, 0, 0.6, OPEN }, { -OPEN / 2 - 0.3, 0, 0.6, OPEN } }) do
        local p = part("Gate" .. g.id .. "_bar", Vector3.new(bar[3], bar[4], 0.6), Vector3.new(0, 0, 0), col, { collide = false, tag = "gate" })
        p.CFrame = cf * CFrame.new(bar[1], bar[2], 0)
    end
    local postH = h - OPEN / 2 - 0.6
    if postH > 0 then
        part("Gate" .. g.id .. "_post", Vector3.new(0.6, postH, 0.6), Vector3.new(cx, postH / 2, cz), col, { tag = "gate" })
    end
    pad("Gate" .. g.id .. "_takeoff", g.takeoff, 1.5, Color3.fromRGB(120, 200, 255))
    pad("Gate" .. g.id .. "_landing", g.landing, 1.5, Color3.fromRGB(120, 255, 160))
    pad("Gate" .. g.id .. "_checkin", checkinPos(g), 1.0, Color3.fromRGB(255, 120, 120))
end
-- COTA loop centreline tiles + transition zone
local loop = W.cota_loop_centreline
for i = 1, #loop do
    local a, b = loop[i], loop[(i % #loop) + 1]
    local dx, dz = b[1] - a[1], b[2] - a[2]
    local len = math.sqrt(dx * dx + dz * dz)
    part("Loop_" .. i, Vector3.new(5, 0.05, len + 0.4), Vector3.new((a[1] + b[1]) / 2, 0.06, (a[2] + b[2]) / 2),
        Color3.fromRGB(60, 60, 60), { collide = false, yaw = math.deg(math.atan2(dx, dz)), tag = "loop" })
end
pad("Pad_N5_Transition", NODES.N5.zone.c, NODES.N5.zone.r, Color3.fromRGB(255, 255, 255))
-- hill ridges with tunnel gaps (roofed)
local TW = NODES.N6.tunnel_width
local RIDGE_H = 7  -- was 3: the 3-stud tunnel roof was lower than a walking humanoid (HRP y about 2.6)
for ri, r in ipairs(NODES.N6.ridges) do
    local x0, x1, tx = r.x[1], r.x[2], r.tunnel_x
    local segs = { { x0, tx - TW / 2 }, { tx + TW / 2, x1 } }
    for si, s in ipairs(segs) do
        if s[2] > s[1] then
            part("Ridge" .. ri .. "_" .. si, Vector3.new(s[2] - s[1], RIDGE_H, 2), Vector3.new((s[1] + s[2]) / 2, RIDGE_H / 2, r.z), Color3.fromRGB(120, 100, 80), { role = "Mesa", tag = "ridge" })
        end
    end
    part("Tunnel" .. ri .. "_roof", Vector3.new(TW + 1, 0.6, 2.4), Vector3.new(tx, RIDGE_H + 0.3, r.z), Color3.fromRGB(100, 84, 66), { role = "Mesa", tag = "tunnel" })
end
pad("Pad_N7_Summit", NODES.N7.zone.c, NODES.N7.zone.r, Color3.fromRGB(255, 215, 0))

-- NPC car pairs on the COTA loop
local npcs = {}
local npcCfg = NODES.N5.npc
local loopLen, cum = 0, { 0 }
for i = 1, #loop do
    local a, b = loop[i], loop[(i % #loop) + 1]
    loopLen = loopLen + math.sqrt((b[1] - a[1]) ^ 2 + (b[2] - a[2]) ^ 2)
    cum[i + 1] = loopLen
end
local function loopPoint(s)
    s = s % loopLen
    for i = 1, #loop do
        if s <= cum[i + 1] then
            local a, b = loop[i], loop[(i % #loop) + 1]
            local f = (s - cum[i]) / math.max(1e-6, cum[i + 1] - cum[i])
            return a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f, math.atan2(b[1] - a[1], b[2] - a[2])
        end
    end
    return loop[1][1], loop[1][2], 0
end
for k = 1, npcCfg.pairs do
    local pair = { s = (k - 1) * loopLen / npcCfg.pairs, cars = {} }
    for side = -1, 1, 2 do
        table.insert(pair.cars, { off = side * 0.8, p = part("NPC" .. k .. "_" .. side, Vector3.new(1.4, 1.2, 2.6), Vector3.new(0, 0.6, 0), Color3.fromRGB(230, 60, 60), { tag = "npc" }) })
    end
    table.insert(npcs, pair)
end

--------------------------------------------------------------------------------
-- RACE STATE
--------------------------------------------------------------------------------
local race = {}       -- player -> state
local reefTaken = nil -- player who holds the reef this heat

local function now() return os.clock() end
local function logEvent(player, ev, data)
    data = data or {}
    data.ev = ev
    data.player = player.Name
    local st = race[player]
    if st and st.t0 then data.t = math.floor((now() - st.t0) * 100 + 0.5) / 100 end
    print("RACE " .. HttpService:JSONEncode(data))
end
local function hrpOf(player)
    local c = player.Character
    return c and c:FindFirstChild("HumanoidRootPart") or nil
end
local function humOf(player)
    local c = player.Character
    return c and c:FindFirstChild("Humanoid") or nil
end
local function inZone(z, x, zz)
    if z.kind == "circle" then
        return (x - z.c[1]) ^ 2 + (zz - z.c[2]) ^ 2 <= z.r ^ 2
    end
    return x >= z.min[1] and x <= z.max[1] and zz >= z.min[2] and zz <= z.max[2]
end
local function near(p, x, z, r) return (x - p[1]) ^ 2 + (z - p[2]) ^ 2 <= r * r end
local function canDo(st, mode)
    for _, m in ipairs(st.model.modes) do if m == mode then return true end end
    return false
end
local function publish(player)
    local st = race[player]
    player:SetAttribute("BotModel", st.model.id)
    player:SetAttribute("RaceState", st.state)
    player:SetAttribute("CurrentNode", st.node or "")
    player:SetAttribute("RaceClock", st.t0 and math.floor((now() - st.t0) * 100) / 100 or 0)
    player:SetAttribute("NodeLog", HttpService:JSONEncode(st.log))
    player:SetAttribute("Penalties", HttpService:JSONEncode(st.pen))
    player:SetAttribute("GateLog", HttpService:JSONEncode(st.gates))
    player:SetAttribute("Laps", st.laps)
    player:SetAttribute("EnergyJ", math.floor(st.energy * 1000) / 1000)
end
local function penal(player, node, reason, s)
    local st = race[player]
    table.insert(st.pen, { node = node, reason = reason, s = s })
    logEvent(player, "PENALTY", { node = node, reason = reason, s = s })
end
local function enterNode(player, id, mode)
    local st = race[player]
    st.node = id
    st.nodeT = now()
    st.mode = mode
    table.insert(st.log, { node = id, enter = math.floor((now() - st.t0) * 100) / 100, mode = mode })
    logEvent(player, "NODE_ENTER", { node = id, mode = mode, parent = st.prev })
end
local function exitNode(player)
    local st = race[player]
    local e = st.log[#st.log]
    e.exit = math.floor((now() - st.t0) * 100) / 100
    e.split = math.floor((e.exit - e.enter) * 100) / 100
    logEvent(player, "NODE_EXIT", { node = st.node, split = e.split })
    st.prev = st.node
    st.node = nil
    st.transitT = now()
end

local function newState(player, modelId)
    local m = MODELS[modelId] or MODELS.wing_swarm
    return { model = m, state = "pen", log = {}, pen = {}, gates = {}, laps = 0, cp = 1, buoy = false,
             energy = DEFAULT_RESERVE_J, speedScale = 1, hop = nil, prev = nil, node = nil, reefHoldT = nil }
end

local function modeFor(st, nodeId)
    return (st.model.nodes and st.model.nodes[nodeId]) or "walk"
end
local function applySpeed(player)
    local st, hum = race[player], humOf(player)
    if not hum then return end
    local v = st.model.speed_studs_s or 5.5
    if st.model.id == "triathlete" and st.node == "N1" then v = SWIM_SPEED end
    if st.model.id == "triathlete" and st.node == "N5" then v = 5.0 end
    hum.WalkSpeed = v * st.speedScale
end

local function startRace(player)
    local st = race[player]
    st.t0 = now(); st.state = "racing"
    enterNode(player, "N0", "release"); exitNode(player)
    applySpeed(player)
end

-- progression: which node can the bot enter next?
local function tryEnter(player, x, y, z)
    local st = race[player]
    local p = st.prev
    if p == "N0" then
        if canDo(st, "swim") and inZone(NODES.N1.zone, x, z) then enterNode(player, "N1", "swim")
        elseif near(NODES.N1.waypoints.shore_path[1], x, z, 2.5) then enterNode(player, "N1", modeFor(st, "N1")) end
    elseif p == "N1" or p == "N1b" then
        if p == "N1" and reefTaken == nil and inZone(NODES.N1b.zone, x, z) then
            for _, a in ipairs(NODES.N1b.allowed_models) do
                if a == st.model.id then reefTaken = player; enterNode(player, "N1b", modeFor(st, "N1b")); st.reefHoldT = now(); return end
            end
        end
        if inZone(NODES.N2.zone, x, z) and z < NODES.N2.zone.min[2] + 4 then enterNode(player, "N2", modeFor(st, "N2")) end
    elseif p == "N2" then
        if inZone(NODES.N3.zone, x, z) then enterNode(player, "N3", modeFor(st, "N3")) end
    elseif p == "N3" then
        if inZone(NODES.N4.zone, x, z) then enterNode(player, "N4", modeFor(st, "N4")) end
    elseif p == "N4" then
        if inZone(NODES.N5.zone, x, z) then enterNode(player, "N5", modeFor(st, "N5")); st.cp = 2; st.laps = 0; applySpeed(player) end
    elseif p == "N5" then
        enterNode(player, "N6", modeFor(st, "N6")); applySpeed(player)
    elseif p == "N6" then
        enterNode(player, "N7", "finish"); exitNode(player); st.state = "finished"
        logEvent(player, "FINISH", { total_raw = st.log[#st.log].exit })
    end
end

local function tryExit(player, x, y, z)
    local st = race[player]
    local id = st.node
    if id == "N1" then
        if st.mode == "swim" then
            if near(NODES.N1.waypoints.buoy, x, z, NODES.N1.waypoints.buoy_r) and not st.buoy then st.buoy = true; logEvent(player, "BUOY", {}) end
            if st.buoy and near(NODES.N1.waypoints.beach_exit, x, z, 3) then exitNode(player) end
        elseif near(NODES.N1.waypoints.shore_path[2], x, z, 2.5) then
            penal(player, "N1", "no_swim_shore_path", NODES.N1.scoring.penalties.no_swim_shore_path_s); exitNode(player)
        end
    elseif id == "N1b" then
        if inZone(NODES.N1b.zone, x, z) then
            if now() - st.reefHoldT >= REEF_HOLD_S then logEvent(player, "REEF_HELD", {}); exitNode(player) end
        else
            st.reefHoldT = now()  -- left the tip: hold timer restarts
        end
    elseif id == "N2" then
        if z > NODES.N2.zone.max[2] then exitNode(player); tryEnter(player, x, y, z) end
    elseif id == "N3" then
        if z > NODES.N3.zone.max[2] then exitNode(player) end
    elseif id == "N4" then
        for _, g in ipairs(NODES.N4.gates) do
            if not st.gates[g.id] then
                if st.hop and near(g.c, x, z, OPEN / 2) and math.abs(y - g.h) <= OPEN / 2 and y > g.h - 1.0 then
                    st.gates[g.id] = "pass"; logEvent(player, "GATE", { gate = g.id, res = "pass" })
                elseif near(checkinPos(g), x, z, 1.2) and y < 4 then
                    st.gates[g.id] = "bypassed_on_foot"; penal(player, "N4", "gate_" .. g.id .. "_bypassed_on_foot", NODES.N4.scoring.penalties.gate_bypassed_on_foot_s)
                end
            end
        end
        local A = NODES.N4.gates[#NODES.N4.gates]
        if near(A.landing, x, z, 2.5) and y < 4 then
            for _, g in ipairs(NODES.N4.gates) do
                if not st.gates[g.id] then st.gates[g.id] = "skipped"; penal(player, "N4", "gate_" .. g.id .. "_skipped", NODES.N4.scoring.penalties.gate_skipped_s) end
            end
            exitNode(player)
        end
    elseif id == "N5" then
        local idx = { 1, 17, 33, 49 }
        local target = loop[idx[st.cp]]
        if target and near(target, x, z, 4) then
            logEvent(player, "CHECKPOINT", { cp = st.cp, lap = st.laps + 1 })
            st.cp = st.cp + 1
            if st.cp > #idx then st.cp = 1 end
            if st.cp == 2 and st.passedOne then st.laps = st.laps + 1; logEvent(player, "LAP", { lap = st.laps }) end
            st.passedOne = true
        end
        local need = (st.mode == "roll") and NODES.N5.laps.roll or NODES.N5.laps.others
        if st.laps >= need and near(NODES.N5.zone.c, x, z, NODES.N5.zone.r) then exitNode(player); tryEnter(player, x, y, z) end
    elseif id == "N6" then
        for ri, r in ipairs(NODES.N6.ridges) do
            if math.abs(z - r.z) < 1.2 and math.abs(x - r.tunnel_x) < TW / 2 and not st["tunnel" .. ri] then
                st["tunnel" .. ri] = true; logEvent(player, "TUNNEL", { ridge = ri })
            end
        end
        if inZone(NODES.N7.zone, x, z) then exitNode(player); tryEnter(player, x, y, z) end
    end
end

--------------------------------------------------------------------------------
-- PLAYERS
--------------------------------------------------------------------------------
local function setupPlayer(player)
    race[player] = newState(player, "wing_swarm")
    local hrp, hum = hrpOf(player), humOf(player)
    if hum then hum.WalkSpeed = 5.5; hum.JumpPower = 50 end
    if hrp then hrp.Position = SPAWN + Vector3.new(#Players:GetPlayers() * 1.5, 0, 0) end
    player:SetAttribute("LastActionResult", "Ready")
    publish(player)
end

local function parsePosition(pos)
    if type(pos) ~= "table" then return nil end
    local x, y, z = tonumber(pos[1]), tonumber(pos[2]), tonumber(pos[3])
    if not x or not y or not z then return nil end
    return Vector3.new(x, y, z)
end

AgentInputService.InputReceived:Connect(function(player, inputType, data)
    local st, hum, hrp = race[player], humOf(player), hrpOf(player)
    if not st or not hum then return end
    data = data or {}
    if inputType == "SelectModel" then
        if st.state ~= "pen" then player:SetAttribute("LastActionResult", "SelectModelFailed:AlreadyStarted"); return end
        local m = MODELS[data.model]
        if not m or m.runnable == false then player:SetAttribute("LastActionResult", "SelectModelFailed:UnknownOrNoData"); return end
        race[player] = newState(player, m.id)
        race[player].speedScale = tonumber(data.speed_scale) or 1
        race[player].energy = tonumber(data.reserve_J) or DEFAULT_RESERVE_J
        player:SetAttribute("SpeedScale", race[player].speedScale)
        player:SetAttribute("LastActionResult", "Model:" .. m.id)
        logEvent(player, "MODEL", { model = m.id, speed_scale = race[player].speedScale })
    elseif inputType == "Start" then
        if st.state ~= "pen" then return end
        startRace(player); player:SetAttribute("LastActionResult", "Started")
    elseif inputType == "MoveTo" then
        local t = parsePosition(data.position)
        if not t then player:SetAttribute("LastActionResult", "MoveToFailed:InvalidPosition"); return end
        hum:MoveTo(t); player:SetAttribute("LastActionResult", "Moving")
    elseif inputType == "Stop" then
        hum:CancelMoveTo()
    elseif inputType == "Jump" then
        hum.Jump = true
    elseif inputType == "Hop" then
        local t = parsePosition(data.to)
        if not canDo(st, "hop") then player:SetAttribute("LastActionResult", "HopFailed:ModelCannotHop"); return end
        if not t or not hrp then player:SetAttribute("LastActionResult", "HopFailed:InvalidTarget"); return end
        if st.energy < HOP_RULE * HOP_COST_J then player:SetAttribute("LastActionResult", "HopDeclined:LowReserve"); logEvent(player, "HOP_DECLINED", { reserve = st.energy }); return end
        local apex = tonumber(data.apex) or (math.max(hrp.Position.Y, t.Y) + 3)
        st.energy = st.energy - HOP_COST_J
        hum:CancelMoveTo()
        st.hop = { a = hrp.Position, b = t, apex = apex, t0 = now(), dur = (tonumber(data.duration) or HOP_AIR_S) / st.speedScale }
        logEvent(player, "HOP", { to = { t.X, t.Y, t.Z }, apex = apex, reserve = st.energy })
        player:SetAttribute("LastActionResult", "Hopping")
    end
end)

RunService.Heartbeat:Connect(function(dt)
    for _, pair in ipairs(npcs) do
        pair.s = pair.s + npcCfg.speed * dt
        local x, z, yaw = loopPoint(pair.s)
        for _, c in ipairs(pair.cars) do
            c.p.CFrame = CFrame.new(x + math.cos(yaw) * c.off, 0.6, z - math.sin(yaw) * c.off) * CFrame.Angles(0, yaw, 0)
        end
    end
    for _, player in ipairs(Players:GetPlayers()) do
        local st, hrp = race[player], hrpOf(player)
        if st and hrp then
            if st.hop then  -- kinematic hop: parabola from a to b peaking at apex
                local f = math.min(1, (now() - st.hop.t0) / st.hop.dur)
                local a, b = st.hop.a, st.hop.b
                local base = a + (b - a) * f
                local y = base.Y + (st.hop.apex - math.max(a.Y, b.Y)) * 4 * f * (1 - f) + (math.max(a.Y, b.Y) - base.Y) * math.sin(math.pi * f)
                hrp.Position = Vector3.new(base.X, y, base.Z)
                hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                if f >= 1 then st.hop = nil; logEvent(player, "LANDED", {}) end
            end
            local p = hrp.Position
            if p.Y < -30 then
                hrp.Position = SPAWN; hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                logEvent(player, "RESET_FALL", {})
            end
            if st.state == "racing" then
                -- non-swimmers may not enter the bay water (reef rock is fine)
                local onReef = inZone({ kind = "box", min = reef.min, max = reef.max }, p.X, p.Z)
                if not canDo(st, "swim") and not st.hop and inZone({ kind = "box", min = bay.min, max = bay.max }, p.X, p.Z) and not onReef and p.Y < 1.5 then
                    local back = NODES.N1.waypoints.shore_path[1]
                    hrp.Position = Vector3.new(back[1], 3, back[2]); humOf(player):CancelMoveTo()
                    player:SetAttribute("LastActionResult", "NoSwim:Returned"); logEvent(player, "NO_SWIM_RETURN", {})
                end
                if st.node then tryExit(player, p.X, p.Y, p.Z) else tryEnter(player, p.X, p.Y, p.Z) end
            end
            publish(player)
        end
    end
end)

Players.PlayerAdded:Connect(setupPlayer)
Players.PlayerRemoving:Connect(function(player)
    if reefTaken == player then reefTaken = nil end
    race[player] = nil
end)
for _, player in ipairs(Players:GetPlayers()) do setupPlayer(player) end

